-- Areas inspected: one row per room or area of a job (kitchen, roof space,
-- subfloor, exterior …) with its inspection status, any access limitation
-- and general overview photos. AS 4349.1 reports must state which areas were
-- inspected and which were not, and why. Written by the inspector app.

create table public.inspection_areas (
  -- Generated by the phone so offline edits keep their identity.
  id uuid primary key,
  job_id uuid not null references public.jobs(id) on delete cascade,
  name text not null,
  kind text not null default 'room',
  status text not null default 'not_started',
  limitation text,
  notes text,
  sort_order integer not null default 0,
  deleted_at timestamptz,
  client_updated_at timestamptz not null,
  created_by_staff_id uuid references public.staff(id) on delete set null,
  updated_by_staff_id uuid references public.staff(id) on delete set null,
  created_at timestamptz not null default now(),
  sync_rev bigint not null default nextval('public.inspection_sync_rev_seq'),
  updated_at timestamptz not null default now(),
  constraint inspection_areas_name_check check (char_length(name) between 1 and 80),
  constraint inspection_areas_kind_check check (
    kind in ('room', 'wet_area', 'roof_exterior', 'roof_space', 'subfloor', 'exterior', 'site', 'outbuilding')
  ),
  constraint inspection_areas_status_check check (
    status in ('not_started', 'inspected', 'limited', 'not_accessible', 'not_applicable')
  ),
  constraint inspection_areas_text_check check (
    char_length(coalesce(limitation, '')) <= 2000 and char_length(coalesce(notes, '')) <= 2000
  )
);

create index inspection_areas_job_idx on public.inspection_areas (job_id, sync_rev);

create trigger inspection_areas_bump_rev
before update on public.inspection_areas
for each row execute function private.bump_sync_rev();

alter table public.inspection_areas enable row level security;
revoke all on table public.inspection_areas from anon, authenticated;
create policy inspection_areas_select_assigned on public.inspection_areas
for select to authenticated using (private.can_view_job(job_id));
grant select on public.inspection_areas to authenticated;

-- A photo belongs to a defect, an area (overview photo), or neither.
alter table public.inspection_photos
  add column if not exists area_id uuid references public.inspection_areas(id) on delete cascade;
create index if not exists inspection_photos_area_idx on public.inspection_photos (area_id);
grant select (area_id) on public.inspection_photos to authenticated;

-- Upserts areas from one phone; the newest edit (phone clock) wins.
create or replace function public.app_sync_areas(
  p_actor_user_id uuid,
  p_job_id uuid,
  p_areas jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_staff public.staff%rowtype;
  v_item jsonb;
  v_existing public.inspection_areas%rowtype;
  v_applied uuid[] := '{}';
  v_stale uuid[] := '{}';
  v_id uuid;
  v_client_at timestamptz;
begin
  v_staff := private.app_actor_for_job(p_actor_user_id, p_job_id);
  if jsonb_typeof(p_areas) <> 'array' or jsonb_array_length(p_areas) > 200 then
    raise exception 'Send between 0 and 200 areas at a time.';
  end if;

  for v_item in select * from jsonb_array_elements(p_areas) loop
    v_id := (v_item->>'id')::uuid;
    v_client_at := (v_item->>'clientUpdatedAt')::timestamptz;
    select * into v_existing from public.inspection_areas where id = v_id for update;
    if found then
      if v_existing.job_id <> p_job_id then raise exception 'Area belongs to another job.'; end if;
      if v_existing.client_updated_at > v_client_at then
        v_stale := v_stale || v_id;
        v_existing := null;
        continue;
      end if;
    end if;

    insert into public.inspection_areas (
      id, job_id, name, kind, status, limitation, notes, sort_order, deleted_at,
      client_updated_at, created_by_staff_id, updated_by_staff_id
    ) values (
      v_id, p_job_id, v_item->>'name', coalesce(v_item->>'kind', 'room'),
      coalesce(v_item->>'status', 'not_started'),
      nullif(v_item->>'limitation', ''), nullif(v_item->>'notes', ''),
      coalesce((v_item->>'sortOrder')::integer, 0),
      case when (v_item->>'deleted')::boolean then coalesce(v_existing.deleted_at, now()) else null end,
      v_client_at, v_staff.id, v_staff.id
    )
    on conflict (id) do update set
      name = excluded.name,
      kind = excluded.kind,
      status = excluded.status,
      limitation = excluded.limitation,
      notes = excluded.notes,
      sort_order = excluded.sort_order,
      deleted_at = excluded.deleted_at,
      client_updated_at = excluded.client_updated_at,
      updated_by_staff_id = excluded.updated_by_staff_id;

    v_applied := v_applied || v_id;
    v_existing := null;
  end loop;

  if cardinality(v_applied) > 0 then
    insert into public.audit_events (job_id, event_type, actor_type, actor_id, event_data)
    values (
      p_job_id, 'app_areas_synced', 'staff', v_staff.id::text,
      jsonb_build_object('applied', cardinality(v_applied), 'stale', cardinality(v_stale))
    );
  end if;
  return jsonb_build_object('applied', to_jsonb(v_applied), 'stale', to_jsonb(v_stale));
end;
$$;

revoke all on function public.app_sync_areas(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.app_sync_areas(uuid, uuid, jsonb) to service_role;

-- Photos may now belong to an area.
create or replace function public.app_register_photo(
  p_actor_user_id uuid,
  p_job_id uuid,
  p_photo jsonb,
  p_storage_path text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_staff public.staff%rowtype;
  v_id uuid := (p_photo->>'id')::uuid;
  v_defect uuid := nullif(p_photo->>'defectId', '')::uuid;
  v_area uuid := nullif(p_photo->>'areaId', '')::uuid;
  v_existing public.inspection_photos%rowtype;
begin
  v_staff := private.app_actor_for_job(p_actor_user_id, p_job_id);
  if v_defect is not null and not exists (
    select 1 from public.inspection_defects where id = v_defect and job_id = p_job_id
  ) then
    raise exception 'Sync the defect before its photos.';
  end if;
  if v_area is not null and not exists (
    select 1 from public.inspection_areas where id = v_area and job_id = p_job_id
  ) then
    raise exception 'Sync the area before its photos.';
  end if;

  select * into v_existing from public.inspection_photos where id = v_id;
  if found then
    if v_existing.job_id <> p_job_id then raise exception 'Photo belongs to another job.'; end if;
    return jsonb_build_object('id', v_id, 'storagePath', v_existing.storage_path, 'uploaded', v_existing.uploaded_at is not null);
  end if;

  insert into public.inspection_photos (
    id, job_id, defect_id, area_id, storage_path, content_type, size_bytes, sha256, width_px, height_px,
    caption, source, captured_at, captured_by_staff_id, sort_order
  ) values (
    v_id, p_job_id, v_defect, v_area, p_storage_path,
    coalesce(p_photo->>'contentType', 'image/jpeg'),
    (p_photo->>'sizeBytes')::integer, lower(p_photo->>'sha256'),
    (p_photo->>'widthPx')::integer, (p_photo->>'heightPx')::integer,
    nullif(p_photo->>'caption', ''), coalesce(p_photo->>'source', 'camera'),
    (p_photo->>'capturedAt')::timestamptz, v_staff.id,
    coalesce((p_photo->>'sortOrder')::integer, 0)
  );
  return jsonb_build_object('id', v_id, 'storagePath', p_storage_path, 'uploaded', false);
end;
$$;

revoke all on function public.app_register_photo(uuid, uuid, jsonb, text) from public, anon, authenticated;
grant execute on function public.app_register_photo(uuid, uuid, jsonb, text) to service_role;
